import{c as s,Q as a,j as t,m as n}from"./chunks/framework.pallWzV6.js";const u=JSON.parse('{"title":"State Tracking","description":"","frontmatter":{},"headers":[],"relativePath":"state-tracking.md","filePath":"state-tracking.md"}'),i={name:"state-tracking.md"};function d(r,e,o,l,p,c){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="state-tracking" tabindex="-1">State Tracking <a class="header-anchor" href="#state-tracking" aria-label="Permalink to &quot;State Tracking&quot;">​</a></h1><p>Seedling records every seeder execution in a <code>seedling_state</code> table that lives in the same database as your seeded data. This gives you an audit trail, drift detection, and the ability to skip seeders that are already up-to-date.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>On the first call to <code>seed run</code> or <code>seed fresh</code>, Seedling automatically creates the <code>seedling_state</code> table (<code>CREATE TABLE IF NOT EXISTS</code>). No migration is needed — it works like Alembic&#39;s <code>alembic_version</code> table.</p><p>Every seeder execution appends one row:</p><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Auto-incrementing primary key</td></tr><tr><td><code>seeder_name</code></td><td>varchar</td><td>Class name of the seeder</td></tr><tr><td><code>env</code></td><td>varchar</td><td>The environment passed to the runner</td></tr><tr><td><code>run_id</code></td><td>varchar(36)</td><td>UUID shared across all seeders in a single <code>run()</code> call</td></tr><tr><td><code>status</code></td><td>varchar</td><td><code>running</code>, <code>success</code>, or <code>error</code></td></tr><tr><td><code>started_at</code></td><td>datetime</td><td>UTC timestamp when the seeder started</td></tr><tr><td><code>finished_at</code></td><td>datetime</td><td>UTC timestamp when the seeder finished (NULL if still running)</td></tr><tr><td><code>duration_ms</code></td><td>integer</td><td>Wall-clock duration in milliseconds</td></tr><tr><td><code>error</code></td><td>text</td><td>Error message if status is <code>error</code></td></tr><tr><td><code>rows_seeded</code></td><td>integer</td><td>Reserved — NULL by default</td></tr><tr><td><code>content_hash</code></td><td>varchar(64)</td><td>SHA-256 of the <code>run()</code> method&#39;s source code</td></tr></tbody></table><p>The history is <strong>append-only</strong>: rows are never deleted between normal runs. They are only deleted when you call <code>seed fresh</code>, which wipes state for the affected seeders before re-seeding.</p><h2 id="drift-detection" tabindex="-1">Drift detection <a class="header-anchor" href="#drift-detection" aria-label="Permalink to &quot;Drift detection&quot;">​</a></h2><p>The <code>content_hash</code> column stores a SHA-256 hash of the seeder&#39;s <code>run()</code> source code at the time it was last executed. When <code>seed status</code> is shown, the current hash is compared to the stored hash. A mismatch means the seeder&#39;s code has changed since it last ran — that run is considered &quot;drifted&quot;.</p><p>Drift is displayed in <code>seed status</code> and is also used by <code>--new-only</code> to decide whether a seeder needs to re-run.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><h3 id="seed-status" tabindex="-1"><code>seed status</code> <a class="header-anchor" href="#seed-status" aria-label="Permalink to &quot;`seed status`&quot;">​</a></h3><p>Show the latest run per seeder with drift detection:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>seed status --env development</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Output:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Seeder status  development</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span> Seeder         Status    Last run              Duration  Drift</span></span>\n<span class="line"><span> ─────────────────────────────────────────────────────────────</span></span>\n<span class="line"><span> UserSeeder     success   2026-05-02 12:00:00   42ms      —</span></span>\n<span class="line"><span> PostSeeder     success   2026-05-02 12:00:01   18ms      ⚠ drift</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Use <code>--json</code> for machine-readable output (useful in CI scripts):</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>seed status --env development --json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="seed-validate" tabindex="-1"><code>seed validate</code> <a class="header-anchor" href="#seed-validate" aria-label="Permalink to &quot;`seed validate`&quot;">​</a></h3><p>Static checks with no database connection required:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>seed validate --env development</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Checks performed:</p><ul><li><strong>Cycles</strong> — any circular <code>depends_on</code> chain raises an error</li><li><strong>Missing deps</strong> — a seeder that references an unregistered dependency</li><li><strong>Empty environments</strong> — a seeder whose <code>environments</code> set is empty will never run</li><li><strong>Missing models</strong> — a seeder without a <code>models</code> list won&#39;t appear in <code>seed export</code></li></ul><p>All issues are printed and the command exits with code 1 if any are found.</p><h3 id="seed-graph" tabindex="-1"><code>seed graph</code> <a class="header-anchor" href="#seed-graph" aria-label="Permalink to &quot;`seed graph`&quot;">​</a></h3><p>Visualize the dependency graph as Graphviz DOT (default) or Mermaid:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Graphviz DOT — pipe to dot for rendering</span></span>\n<span class="line"><span>seed graph | dot -Tpng -o deps.png</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span># Mermaid — paste into a .md file or Mermaid Live Editor</span></span>\n<span class="line"><span>seed graph --mermaid</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="run-flags" tabindex="-1">Run flags <a class="header-anchor" href="#run-flags" aria-label="Permalink to &quot;Run flags&quot;">​</a></h2><h3 id="new-only" tabindex="-1"><code>--new-only</code> <a class="header-anchor" href="#new-only" aria-label="Permalink to &quot;`--new-only`&quot;">​</a></h3><p>Skip seeders whose latest state is <code>success</code> <strong>and</strong> whose <code>content_hash</code> matches the current source. Seeders that have never run, last failed, or have drifted will always run.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>seed run --new-only</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This is the opt-in idempotency flag. <code>seed run</code> without <code>--new-only</code> always runs all seeders and records the result.</p><h3 id="force" tabindex="-1"><code>--force</code> <a class="header-anchor" href="#force" aria-label="Permalink to &quot;`--force`&quot;">​</a></h3><p>Override <code>--new-only</code> and run all seeders regardless of state:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>seed run --new-only --force</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="max-parallel-n" tabindex="-1"><code>--max-parallel N</code> <a class="header-anchor" href="#max-parallel-n" aria-label="Permalink to &quot;`--max-parallel N`&quot;">​</a></h3><p>Cap how many seeders run concurrently within a single dependency level:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>seed run --max-parallel 2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Without this flag, all seeders in the same level run in parallel (the 0.2 default).</p><h2 id="transactional-mode" tabindex="-1">Transactional mode <a class="header-anchor" href="#transactional-mode" aria-label="Permalink to &quot;Transactional mode&quot;">​</a></h2><p><code>SeederRunner(transactional=True)</code> wraps the entire run in a single transaction. All seeders share one session; if any seeder raises, the entire transaction rolls back.</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">runner </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SeederRunner(session_factory, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;test&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">transactional</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Note:</strong> State tracking is skipped in transactional mode. Because the seeder data and state rows would be in the same transaction, a rollback would also roll back the state records, making them unreliable. Use transactional mode for test isolation, not production audit.</p><h2 id="opting-out" tabindex="-1">Opting out <a class="header-anchor" href="#opting-out" aria-label="Permalink to &quot;Opting out&quot;">​</a></h2><p>Disable state tracking globally for a project via <code>pyproject.toml</code>:</p><div class="language-toml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">seedling</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">runner = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myapp.seeders:create_runner&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">state_tracking = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Or per <code>SeederRunner</code> instance:</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">runner </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SeederRunner(session_factory, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;development&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">state_tracking</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">False</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>When disabled, the <code>seedling_state</code> table is never created or queried.</p><h2 id="the-fresh-command-and-state" tabindex="-1">The <code>fresh</code> command and state <a class="header-anchor" href="#the-fresh-command-and-state" aria-label="Permalink to &quot;The `fresh` command and state&quot;">​</a></h2><p><code>seed fresh</code> wipes state for all affected seeders <strong>before</strong> truncating tables and re-seeding. This gives you a clean slate — history for those seeders in that environment is gone. This is intentional: <code>fresh</code> means &quot;start over.&quot;</p><p>State for seeders in other environments is untouched.</p>',52)])])}const m=s(i,[["render",d]]);export{u as __pageData,m as default};
